from __future__ import annotations

import dataclasses

from microvm.errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {
        "let",
        "print",
        "if",
        "else",
        "while",
        "true",
        "false",
        "and",
        "or",
        "not",
    }
)
_TWO_CHAR_OPS: frozenset[str] = frozenset({"==", "!=", "<=", ">="})
_ONE_CHAR_OPS: frozenset[str] = frozenset(list("+-*/%(){};=<>"))
_ESCAPES: dict[str, str] = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in " \t\n\r":
            i += 1
            continue
        if ch == "/" and i + 1 < n and src[i + 1] == "/":
            i = src.find("\n", i + 2)
            i = n if i < 0 else i
            continue
        nxt, i = _next_token(src, i, n)
        tokens.append(nxt)
    return tokens


def _next_token(src: str, i: int, n: int) -> tuple[Token, int]:
    ch = src[i]
    if ch == '"':
        return _read_string(src, i, n)
    if ch.isdigit():
        return _read_number(src, i, n)
    if ch.isalpha() or ch == "_":
        return _read_ident(src, i, n)
    two = src[i : i + 2]
    if two in _TWO_CHAR_OPS:
        return Token("OP", two, two, i), i + 2
    if ch in _ONE_CHAR_OPS:
        return Token("OP", ch, ch, i), i + 1
    raise LexError(f"unexpected character {ch!r}", i)


def _read_ident(src: str, i: int, n: int) -> tuple[Token, int]:
    start = i
    i += 1
    while i < n and (src[i].isalnum() or src[i] == "_"):
        i += 1
    text = src[start:i]
    kind = "KEYWORD" if text in KEYWORDS else "IDENT"
    return Token(kind, text, text, start), i


def _read_number(src: str, i: int, n: int) -> tuple[Token, int]:
    start = i
    while i < n and src[i].isdigit():
        i += 1
    if i < n and src[i] == ".":
        return _read_float(src, start, i, n)
    text = src[start:i]
    return Token("INT", text, int(text), start), i


def _read_float(src: str, start: int, i: int, n: int) -> tuple[Token, int]:
    if i + 1 >= n or not src[i + 1].isdigit():
        raise LexError("float requires digits on both sides of the dot", start)
    i += 1
    while i < n and src[i].isdigit():
        i += 1
    if i < n and src[i] in "eE":
        i = _consume_exponent(src, start, i, n)
    text = src[start:i]
    return Token("FLOAT", text, float(text), start), i


def _consume_exponent(src: str, start: int, i: int, n: int) -> int:
    i += 1
    if i < n and src[i] in "+-":
        i += 1
    if i >= n or not src[i].isdigit():
        raise LexError("invalid float exponent", start)
    while i < n and src[i].isdigit():
        i += 1
    return i


def _read_string(src: str, i: int, n: int) -> tuple[Token, int]:
    start = i
    i += 1
    chars: list[str] = []
    while i < n:
        ch = src[i]
        if ch == "\n":
            raise LexError("newline in string", i)
        if ch == '"':
            decoded = "".join(chars)
            return Token("STRING", decoded, decoded, start), i + 1
        if ch == "\\":
            chars.append(_unescape(src, i, n, start))
            i += 2
            continue
        chars.append(ch)
        i += 1
    raise LexError("unterminated string", start)


def _unescape(src: str, i: int, n: int, start: int) -> str:
    if i + 1 >= n:
        raise LexError("unterminated string", start)
    nxt = src[i + 1]
    if nxt not in _ESCAPES:
        raise LexError("invalid escape sequence", i)
    return _ESCAPES[nxt]

from __future__ import annotations

from dataclasses import dataclass

from microvm.errors import ParseError
from microvm.lexer import Token, tokenize

_CMP_OPS: frozenset[str] = frozenset({"==", "!=", "<", "<=", ">", ">="})
_ADD_OPS: frozenset[str] = frozenset({"+", "-"})
_MUL_OPS: frozenset[str] = frozenset({"*", "/", "%"})


@dataclass
class Script:
    statements: list[object]


@dataclass
class Block:
    statements: list[object]
    offset: int


@dataclass
class Let:
    name: str
    expr: object
    offset: int


@dataclass
class Assign:
    name: str
    expr: object
    offset: int


@dataclass
class Print:
    expr: object
    offset: int


@dataclass
class If:
    cond: object
    then_body: object
    else_body: object | None
    offset: int


@dataclass
class While:
    cond: object
    body: object
    offset: int


@dataclass
class Literal:
    value: object
    offset: int


@dataclass
class Name:
    name: str
    offset: int


@dataclass
class Unary:
    op: str
    expr: object
    offset: int


@dataclass
class Binary:
    op: str
    left: object
    right: object
    offset: int


def parse(src: str) -> object:
    return _Parser(tokenize(src), src).parse_script()


class _Parser:
    def __init__(self, tokens: list[Token], src: str) -> None:
        self.tokens = tokens
        self.src = src
        self.pos = 0

    def parse_script(self) -> Script:
        stmts: list[object] = []
        while self._cur() is not None:
            stmts.append(self.parse_stmt())
        return Script(stmts)

    def parse_stmt(self) -> object:
        tok = self._need()
        if tok.kind == "KEYWORD":
            return self._stmt_keyword(tok)
        if tok.kind == "OP" and tok.text == "{":
            return self.parse_block()
        if tok.kind == "IDENT":
            return self.parse_assign()
        self._error("expected statement", tok.offset)
        raise AssertionError("unreachable")

    def _stmt_keyword(self, tok: Token) -> object:
        if tok.text == "let":
            return self.parse_let()
        if tok.text == "print":
            return self.parse_print()
        if tok.text == "if":
            return self.parse_if()
        if tok.text == "while":
            return self.parse_while()
        self._error("expected statement", tok.offset)
        raise AssertionError("unreachable")

    def parse_let(self) -> Let:
        tok = self._expect_kw("let")
        name = self._expect_kind("IDENT")
        self._expect_op("=")
        expr = self.parse_expr()
        self._expect_op(";")
        return Let(name.text, expr, tok.offset)

    def parse_assign(self) -> Assign:
        name = self._expect_kind("IDENT")
        self._expect_op("=")
        expr = self.parse_expr()
        self._expect_op(";")
        return Assign(name.text, expr, name.offset)

    def parse_print(self) -> Print:
        tok = self._expect_kw("print")
        expr = self.parse_expr()
        self._expect_op(";")
        return Print(expr, tok.offset)

    def parse_if(self) -> If:
        tok = self._expect_kw("if")
        self._expect_op("(")
        cond = self.parse_expr()
        self._expect_op(")")
        then = self.parse_block()
        else_body: object | None = None
        if self._is_kw("else"):
            self._advance()
            if self._is_kw("if"):
                else_body = self.parse_if()
            else:
                else_body = self.parse_block()
        return If(cond, then, else_body, tok.offset)

    def parse_while(self) -> While:
        tok = self._expect_kw("while")
        self._expect_op("(")
        cond = self.parse_expr()
        self._expect_op(")")
        return While(cond, self.parse_block(), tok.offset)

    def parse_block(self) -> Block:
        tok = self._expect_op("{")
        stmts: list[object] = []
        while not self._is_op("}"):
            if self._cur() is None:
                self._error("unclosed block", len(self.src))
            stmts.append(self.parse_stmt())
        self._expect_op("}")
        return Block(stmts, tok.offset)

    def parse_expr(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        return self._bin_loop(self.parse_and, self._is_kw, "or")

    def parse_and(self) -> object:
        return self._bin_loop(self.parse_not, self._is_kw, "and")

    def parse_not(self) -> object:
        tok = self._cur()
        if tok is not None and tok.kind == "KEYWORD" and tok.text == "not":
            self._advance()
            return Unary("not", self.parse_not(), tok.offset)
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        left = self.parse_additive()
        tok = self._cur()
        if tok is None or tok.kind != "OP" or tok.text not in _CMP_OPS:
            return left
        self._advance()
        right = self.parse_additive()
        nxt = self._cur()
        if nxt is not None and nxt.kind == "OP" and nxt.text in _CMP_OPS:
            self._error("chained comparison is not allowed", nxt.offset)
        return Binary(tok.text, left, right, tok.offset)

    def parse_additive(self) -> object:
        return self._op_loop(self.parse_multiplicative, _ADD_OPS)

    def parse_multiplicative(self) -> object:
        return self._op_loop(self.parse_unary, _MUL_OPS)

    def parse_unary(self) -> object:
        tok = self._cur()
        if tok is not None and tok.kind == "OP" and tok.text == "-":
            self._advance()
            return Unary("-", self.parse_unary(), tok.offset)
        return self.parse_primary()

    def parse_primary(self) -> object:
        tok = self._need_expr()
        if tok.kind in {"INT", "FLOAT", "STRING"}:
            self._advance()
            return Literal(tok.value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text in {"true", "false"}:
            self._advance()
            return Literal(tok.text == "true", tok.offset)
        if tok.kind == "IDENT":
            self._advance()
            return Name(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self._advance()
            expr = self.parse_expr()
            self._expect_op(")")
            return expr
        self._error("expected expression", tok.offset)
        raise AssertionError("unreachable")

    def _bin_loop(self, inner: object, pred: object, word: str) -> object:
        left = inner()  # type: ignore[operator]
        while pred(word):  # type: ignore[operator]
            op = self._advance()
            right = inner()  # type: ignore[operator]
            left = Binary(word, left, right, op.offset)
        return left

    def _op_loop(self, inner: object, ops: frozenset[str]) -> object:
        left = inner()  # type: ignore[operator]
        while True:
            tok = self._cur()
            if tok is None or tok.kind != "OP" or tok.text not in ops:
                return left
            self._advance()
            left = Binary(tok.text, left, inner(), tok.offset)  # type: ignore[operator]

    def _cur(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _need(self) -> Token:
        tok = self._cur()
        if tok is None:
            self._error("unexpected end of input", len(self.src))
        return tok  # type: ignore[return-value]

    def _need_expr(self) -> Token:
        tok = self._cur()
        if tok is None:
            self._error("expected expression", len(self.src))
        return tok  # type: ignore[return-value]

    def _advance(self) -> Token:
        tok = self._need()
        self.pos += 1
        return tok

    def _is_kw(self, word: str) -> bool:
        tok = self._cur()
        return tok is not None and tok.kind == "KEYWORD" and tok.text == word

    def _is_op(self, text: str) -> bool:
        tok = self._cur()
        return tok is not None and tok.kind == "OP" and tok.text == text

    def _expect_kw(self, word: str) -> Token:
        tok = self._need()
        if tok.kind != "KEYWORD" or tok.text != word:
            self._error(f"expected {word}", tok.offset)
        return self._advance()

    def _expect_op(self, text: str) -> Token:
        tok = self._need()
        if tok.kind != "OP" or tok.text != text:
            self._error(f"expected {text!r}", tok.offset)
        return self._advance()

    def _expect_kind(self, kind: str) -> Token:
        tok = self._need()
        if tok.kind != kind:
            self._error(f"expected {kind}", tok.offset)
        return self._advance()

    def _error(self, message: str, offset: int) -> None:
        raise ParseError(message, offset)

from __future__ import annotations

from microvm.parser import (
    Assign,
    Binary,
    Block,
    If,
    Let,
    Literal,
    Name,
    Print,
    Script,
    Unary,
    While,
)


def fold_constants(node: object) -> object:
    if isinstance(node, Script):
        return Script([fold_constants(s) for s in node.statements])
    if isinstance(node, Block):
        return Block([fold_constants(s) for s in node.statements], node.offset)
    if isinstance(node, (Let, Assign, Print, If, While, Unary, Binary)):
        return _fold_compound(node)
    return node


def _fold_compound(node: object) -> object:
    if isinstance(node, Let):
        return Let(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, Assign):
        return Assign(node.name, fold_constants(node.expr), node.offset)
    if isinstance(node, Print):
        return Print(fold_constants(node.expr), node.offset)
    if isinstance(node, If):
        else_body = None if node.else_body is None else fold_constants(node.else_body)
        return If(fold_constants(node.cond), fold_constants(node.then_body), else_body, node.offset)
    if isinstance(node, While):
        return While(fold_constants(node.cond), fold_constants(node.body), node.offset)
    if isinstance(node, Unary):
        return _fold_unary(node)
    if isinstance(node, Binary):
        return _fold_binary(node)
    return node


def _fold_unary(node: Unary) -> object:
    expr = fold_constants(node.expr)
    if isinstance(expr, Literal):
        folded = _eval_unary(node.op, expr.value)
        if folded is not _FAIL:
            return Literal(folded, node.offset)
    return Unary(node.op, expr, node.offset)


def _fold_binary(node: Binary) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if node.op == "and":
        return _fold_and(left, right, node.offset)
    if node.op == "or":
        return _fold_or(left, right, node.offset)
    if isinstance(left, Literal) and isinstance(right, Literal):
        folded = _eval_binary(node.op, left.value, right.value)
        if folded is not _FAIL:
            return Literal(folded, node.offset)
    return Binary(node.op, left, right, node.offset)


def _fold_and(left: object, right: object, offset: int) -> object:
    if isinstance(left, Literal) and type(left.value) is bool and left.value is False:
        return Literal(False, offset)
    if _both_bool_lits(left, right):
        return Literal(left.value and right.value, offset)  # type: ignore[union-attr]
    return Binary("and", left, right, offset)


def _fold_or(left: object, right: object, offset: int) -> object:
    if isinstance(left, Literal) and type(left.value) is bool and left.value is True:
        return Literal(True, offset)
    if _both_bool_lits(left, right):
        return Literal(left.value or right.value, offset)  # type: ignore[union-attr]
    return Binary("or", left, right, offset)


def _both_bool_lits(left: object, right: object) -> bool:
    return (
        isinstance(left, Literal)
        and isinstance(right, Literal)
        and type(left.value) is bool
        and type(right.value) is bool
    )


_FAIL = object()


def _is_num(value: object) -> bool:
    return type(value) is int or type(value) is float


def _eval_unary(op: str, value: object) -> object:
    if op == "-" and _is_num(value):
        return -value  # type: ignore[operator]
    if op == "not" and type(value) is bool:
        return not value
    return _FAIL


def _eval_binary(op: str, left: object, right: object) -> object:
    if op in {"==", "!="}:
        eq = _eq(left, right)
        return eq if op == "==" else (not eq)
    if op in {"+", "-", "*", "/", "%"}:
        return _eval_arith(op, left, right)
    if op in {"<", "<=", ">", ">="}:
        return _eval_cmp(op, left, right)
    return _FAIL


def _eval_arith(op: str, left: object, right: object) -> object:
    if op == "+" and type(left) is str and type(right) is str:
        return left + right
    if op == "%" and type(left) is int and type(right) is int:
        if right == 0:
            return _FAIL
        return left % right
    if not (_is_num(left) and _is_num(right)):
        return _FAIL
    if op == "/":
        if right == 0:
            return _FAIL
        return float(left) / float(right)
    if op == "+":
        return left + right  # type: ignore[operator]
    if op == "-":
        return left - right  # type: ignore[operator]
    if op == "*":
        return left * right  # type: ignore[operator]
    return _FAIL


def _eval_cmp(op: str, left: object, right: object) -> object:
    ok_num = _is_num(left) and _is_num(right)
    ok_str = type(left) is str and type(right) is str
    if not (ok_num or ok_str):
        return _FAIL
    if op == "<":
        return left < right  # type: ignore[operator]
    if op == "<=":
        return left <= right  # type: ignore[operator]
    if op == ">":
        return left > right  # type: ignore[operator]
    return left >= right  # type: ignore[operator]


def _eq(left: object, right: object) -> bool:
    if type(left) is bool or type(right) is bool:
        return type(left) is bool and type(right) is bool and left is right
    if _is_num(left) and _is_num(right):
        return bool(left == right)
    return type(left) is type(right) and left == right

from __future__ import annotations

from dataclasses import dataclass, field

from microvm.errors import CompileError
from microvm.opcodes import HAS_ARG, OPCODES
from microvm.optimizer import fold_constants
from microvm.parser import (
    Assign,
    Binary,
    Block,
    If,
    Let,
    Literal,
    Name,
    Print,
    Script,
    Unary,
    While,
    parse,
)

_BIN_OPS: dict[str, str] = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


@dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclass
class Program:
    constants: list[object]
    names: list[str]
    instructions: list[Instr]


def compile_source(src: str, *, optimize: bool = False) -> Program:
    tree = parse(src)
    if optimize:
        tree = fold_constants(tree)
    gen = _Gen()
    gen.collect(tree)
    gen.compile(tree)
    gen.emit("HALT")
    return Program(gen.constants, gen.names, gen.ins)


class _Gen:
    def __init__(self) -> None:
        self.constants: list[object] = []
        self._const_key: dict[tuple[type, object], int] = {}
        self.names: list[str] = []
        self._name_slot: dict[str, int] = {}
        self.ins: list[Instr] = []

    def emit(self, op: str, arg: int | None = None) -> int:
        if op not in OPCODES:
            raise CompileError(f"unknown opcode {op}")
        if (op in HAS_ARG) != (arg is not None):
            raise CompileError(f"bad argument for {op}")
        self.ins.append(Instr(op, arg))
        return len(self.ins) - 1

    def add_const(self, value: object) -> int:
        key = (type(value), value)
        idx = self._const_key.get(key)
        if idx is None:
            idx = len(self.constants)
            self._const_key[key] = idx
            self.constants.append(value)
        return idx

    def slot(self, name: str) -> int:
        if name not in self._name_slot:
            raise CompileError(f"undeclared name {name}")
        return self._name_slot[name]

    def collect(self, node: object) -> None:
        if isinstance(node, (Script, Block)):
            for stmt in node.statements:
                self.collect(stmt)
        elif isinstance(node, Let):
            self._declare(node.name)
            self.collect(node.expr)
        elif isinstance(node, (Assign, Print)):
            self.collect(node.expr)
        elif isinstance(node, If):
            self.collect(node.cond)
            self.collect(node.then_body)
            if node.else_body is not None:
                self.collect(node.else_body)
        elif isinstance(node, While):
            self.collect(node.cond)
            self.collect(node.body)
        elif isinstance(node, Binary):
            self.collect(node.left)
            self.collect(node.right)
        elif isinstance(node, Unary):
            self.collect(node.expr)

    def _declare(self, name: str) -> None:
        if name in self._name_slot:
            raise CompileError(f"duplicate declaration of {name}")
        self._name_slot[name] = len(self.names)
        self.names.append(name)

    def compile(self, node: object) -> None:
        if isinstance(node, Script):
            for stmt in node.statements:
                self.compile(stmt)
        elif isinstance(node, Block):
            for stmt in node.statements:
                self.compile(stmt)
        elif isinstance(node, Let):
            self.compile(node.expr)
            self.emit("STORE", self.slot(node.name))
        elif isinstance(node, Assign):
            self.compile(node.expr)
            self.emit("STORE", self.slot(node.name))
        elif isinstance(node, Print):
            self.compile(node.expr)
            self.emit("PRINT")
        elif isinstance(node, If):
            self._compile_if(node)
        elif isinstance(node, While):
            self._compile_while(node)
        else:
            self.compile_expr(node)

    def compile_expr(self, node: object) -> None:
        if isinstance(node, Literal):
            self.emit("CONST", self.add_const(node.value))
        elif isinstance(node, Name):
            self.emit("LOAD", self.slot(node.name))
        elif isinstance(node, Unary):
            self.compile_expr(node.expr)
            self.emit("NEG" if node.op == "-" else "NOT")
        elif isinstance(node, Binary):
            self._compile_binary(node)
        else:
            raise CompileError("invalid expression")

    def _compile_binary(self, node: Binary) -> None:
        if node.op == "and":
            self._compile_and(node)
            return
        if node.op == "or":
            self._compile_or(node)
            return
        self.compile_expr(node.left)
        self.compile_expr(node.right)
        self.emit(_BIN_OPS[node.op])

    def _compile_and(self, node: Binary) -> None:
        # JUMP_IF_FALSE pops; restore false when skipping the right operand.
        self.compile_expr(node.left)
        jfalse = self.emit("JUMP_IF_FALSE", 0)
        self.compile_expr(node.right)
        self.emit("NOT")
        self.emit("NOT")
        jend = self.emit("JUMP", 0)
        self.ins[jfalse] = Instr("JUMP_IF_FALSE", len(self.ins))
        self.emit("CONST", self.add_const(False))
        self.ins[jend] = Instr("JUMP", len(self.ins))

    def _compile_or(self, node: Binary) -> None:
        self.compile_expr(node.left)
